$target=Join-Path $PSScriptRoot '..\admin-panel\app\hadith\page.tsx';$source=Get-Content $target -Raw -Encoding utf8
$old='const visible=useMemo\(.*?\);const set='
$new='const languageRows=useMemo(()=>language==="en"?[...items,...existing.filter(x=>!items.some(saved=>saved.collectionId===x.collectionId&&String(saved.hadithNumber)===String(x.hadithNumber)))]:items.filter(x=>x.translations?.[language]).map(x=>({...x,...x.translations[language],id:x.id,arabic:x.arabic,translations:x.translations,published:x.published})),[items,existing,language]);const visible=useMemo(()=>languageRows.filter(x=>`${x.collectionName} ${x.hadithNumber} ${x.title} ${x.text}`.toLowerCase().includes(query.toLowerCase())).slice(0,250),[languageRows,query]);const set='
$source=[regex]::Replace($source,$old,$new)
$source=$source.Replace('{existingLoading?"Loading existing app content...":`${existing.length} existing in selected collection`}','{language==="en"?(existingLoading?"Loading existing app content...":`${existing.length} English records in selected collection`):`${languageRows.length} Hadith translated in ${languages.find(x=>x.code===language)?.label||language.toUpperCase()}`}')
$source=$source.Replace('<span>Total source records: {existing.length}. Bukhari Hadith numbers run from 1 to 7563.</span>','<span>{language==="en"?`Total source records: ${existing.length}`:`Only saved ${languages.find(x=>x.code===language)?.label||language.toUpperCase()} translations are shown`}</span>')
$source=$source.Replace("onClick={()=>edit(x,'en')}","onClick={()=>edit(x,language)}")
$source=$source.Replace('<b>No matching Hadith number or text</b><span>7589 is the total record count, not a Hadith number. Try a number from 1 to 7563.</span>','<b>No content found for this language</b><span>{language==="en"?"Try another Hadith number or text.":"Import an English Hadith, then save its translation in the selected language."}</span>')
Set-Content $target $source -NoNewline -Encoding utf8
